    if(!Array.isArray(r.markets) || r.markets.some(function(m){return !['Crypto','Stocks','Forex','Macro','Commodities'].includes(m);}))throw Error('Invalid market coverage.');
    stages.forEach(function(stage){if(r.workflow[stage]!=null && typeof r.workflow[stage]!=='boolean')throw Error('Invalid workflow state.');});
    if(r.storyData){var d=r.storyData;if(!Array.isArray(d.assets))throw Error('Invalid captured assets.');d.assets.forEach(function(a){if(!a || typeof a.id!=='string' || typeof a.symbol!=='string' || typeof a.market!=='string' || (a.p7!=null && (typeof a.p7!=='number' || !Number.isFinite(a.p7))))throw Error('Invalid asset observation.');});if(d.news && (!Array.isArray(d.news) || d.news.some(function(n){return !n || typeof n.title!=='string' || !safeUrl(n.url);})))throw Error('Invalid captured news.');['BTC','ETH'].forEach(function(key){var e=d.etf && d.etf[key];if(e && e.bars && !Array.isArray(e.bars))throw Error('Invalid ETF history.');});}
