  function options(){return runs.map(function(r){return '<option value="'+esc(r.id)+'">'+esc(r.date+' · '+r.title)+'</option>';}).join('');}
  function compare(){var a=runs.find(function(r){return r.id===document.getElementById('rr-left').value;}), b=runs.find(function(r){return r.id===document.getElementById('rr-right').value;});if(!a||!b||a.id===b.id)return message('Choose two different saved runs.');document.getElementById('rr-comparison').innerHTML='<div class="rr-table-wrap"><table><thead><tr><th>Observation</th><th>'+esc(a.title)+'</th><th>'+esc(b.title)+'</th></tr></thead><tbody>'+['date','regime','fearGreed','strongest','weakest','changes','paths','narrative','returnNotes'].map(function(f){return '<tr><th>'+esc(f)+'</th><td>'+esc(a[f]||'Not recorded')+'</td><td>'+esc(b[f]||'Not recorded')+'</td></tr>';}).join('')+'</tbody></table></div>';}
  async function importFile(e){try{if(dirty)throw Error('Save your open edits before importing.');var file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error('Backup is too large (maximum 5 MB).');var data=JSON.parse(await file.text()),r=data.run;if(data.schema!=='rotator.research-package.v1'||!r||typeof r.id!=='string'||!Array.isArray(r.markets)||!r.workflow||typeof r.workflow!=='object')throw Error('This is not a Rotator research backup.');fields.forEach(function(f){if(r[f]!=null&&typeof r[f]!=='string')throw Error('Invalid field: '+f);});validate(r);if(runs.some(function(x){return x.id===r.id;}))throw Error('This run already exists. Import will not overwrite it.');r.revision=Number.isInteger(r.revision)?r.revision:0;runs.unshift(r);try{persist();}catch(err){runs.shift();throw err;}selected=r.id;render();message('Research backup imported.');}catch(err){message(err.message);}}
  root.addEventListener('click',function(e){var button=e.target.closest('button');if(!button)return;try{if(button.dataset.run){if(dirty){message('Save your open edits before switching runs.');return;}selected=button.dataset.run;dirty=false;render();return;}var a=button.dataset.action;if(a==='topic'){if(busy)return;if(dirty){message('Save your edits before capturing a new run.');return;}pendingFocus=button.dataset.topic;root.querySelectorAll('[data-action="topic"]').forEach(function(b){var on=b.dataset.topic===pendingFocus;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});captureReady();}if(a==='output')captureReady(button.dataset.format);if(a==='copy-output')copyText(document.getElementById('rr-output-text').value);if(a==='download-output')download(document.getElementById('rr-output-text').value,'rotator-story.txt','text/plain');if(a==='new')create(false);if(a==='capture')captureReady();if(a==='save')save();if(a==='drafts')drafts(false);if(a==='confirm-drafts')drafts(true);if(a==='cancel-drafts')message('Current draft text kept.');if(a==='preview')previewStory();if(a==='article')exportArticle();if(a==='markdown'){var md=collect();window.RotatorStory.assertFresh(md);download(window.RotatorPublication.markdown(md),'rotator-map-'+md.id+'.md','text/markdown');}if(a==='copy-telegram'){var tg=collect();window.RotatorPublication.assertSocial(tg);if(!tg.telegram)throw Error('Build the Telegram draft first.');navigator.clipboard.writeText(tg.telegram).then(function(){message('Telegram draft copied.');}).catch(function(){message('Clipboard unavailable. Copy the text under Edit the article & Telegram text.');});}if(a==='distribution')refreshDistribution();if(a==='kit')exportPublicationKit();if(a==='copy-article')copyArticle();if(a==='copy-headline')copyText(window.RotatorPublication.angle(collect()).headline);if(a==='copy-threads'){var th=collect();window.RotatorPublication.assertSocial(th);copyText(th.threadsText);}if(a==='copy-instagram'){var ig=collect();window.RotatorPublication.assertSocial(ig);copyText(ig.instagramCaption);}if(a==='copy-alt'){var alt=collect();copyText(alt.instagramAlt);}if(a==='social-graph')exportSocialGraph(button.dataset.channel);if(a==='graph-package')exportGraphPackage(button.dataset.graph);if(a==='graph')exportGraph(button.dataset.graph,true);if(a==='svg')exportGraph(button.dataset.graph,false);if(a==='export')exportRun(true);if(a==='backup')exportRun(false);if(a==='compare')compare();if(a==='import')document.getElementById('rr-file').click();}catch(err){message(err.message);}});
  window.addEventListener('beforeunload',function(e){if(dirty){e.preventDefault();e.returnValue='';}});
  /* Same-page agent interface: explicit, versioned mutations. No send/publish action. */
  window.RotatorResearch = Object.freeze({version:3, refreshDistribution:function(id,expectedRevision){if(dirty)throw Error('Save open UI edits first.');var i=runs.findIndex(function(r){return r.id===id;});if(i<0)throw Error('Run not found');if(runs[i].revision!==expectedRevision)throw Error('Revision conflict');var old=runs[i];window.RotatorStory.assertFresh(old);var next=Object.assign({},old,window.RotatorPublication.components(old));next.revision++;next.updatedAt=new Date().toISOString();runs[i]=next;try{persist();}catch(e){runs[i]=old;throw e;}render();return JSON.parse(JSON.stringify(next));}, exportPublication:function(id){var r=runs.find(function(x){return x.id===id;});if(!r)throw Error('Run not found');return window.RotatorPublication.package(r);}, captureReady:captureReady, buildArticle:function(id,expectedRevision){if(dirty)throw Error('Save open UI edits first.');var i=runs.findIndex(function(r){return r.id===id;});if(i<0)throw Error('Run not found');if(runs[i].revision!==expectedRevision)throw Error('Revision conflict');var old=runs[i],built=window.RotatorStory.build(old);built.revision++;built.updatedAt=new Date().toISOString();runs[i]=built;try{persist();}catch(e){runs[i]=old;throw e;}render();window.dispatchEvent(new CustomEvent('rotator:research-saved',{detail:{id:id,revision:built.revision}}));return JSON.parse(JSON.stringify(built));}, createManual:function(){if(dirty)throw Error('Save open UI edits first.');return create(false);}, captureCurrent:function(){if(dirty)throw Error('Save open UI edits first.');return create(true);}, list:function(){return JSON.parse(JSON.stringify(runs));}, get:function(id){return JSON.parse(JSON.stringify(runs.find(function(r){return r.id===id;})||null));}, exportPackage:function(id){var r=runs.find(function(x){return x.id===id;});if(!r)throw Error('Run not found');return packageRun(r,true);}, update:function(id,patch,expectedRevision){if(dirty)throw Error('Save open UI edits first.');var i=runs.findIndex(function(r){return r.id===id;});if(i<0)throw Error('Run not found');var old=runs[i];if(old.revision!==expectedRevision)throw Error('Revision conflict');var r=JSON.parse(JSON.stringify(old));Object.keys(patch).forEach(function(f){if(!fields.includes(f)&&f!=='workflow'&&f!=='story'&&f!=='reviewed'&&f!=='focusTopic')throw Error('Unsupported field: '+f);if(f==='focusTopic'){if(typeof patch[f]!=='string')throw Error('Edition focus must be text');r=window.RotatorPublication.applyPreset(r,patch[f],r.story && r.story.affected && r.story.affected[0]);}else if(f==='reviewed'){if(typeof patch[f]!=='boolean')throw Error('Review state must be boolean');r.reviewed=patch[f];}else if(f==='story'){ r.story=JSON.parse(JSON.stringify(patch.story)); validateStory(r.story); }else if(f==='workflow'){stages.forEach(function(s){if(s in patch.workflow){if(typeof patch.workflow[s]!=='boolean')throw Error('Workflow values must be boolean');r.workflow[s]=patch.workflow[s];}});}else{if(typeof patch[f]!=='string')throw Error('Field must be text');r[f]=patch[f];}});validate(r);r.revision++;r.updatedAt=new Date().toISOString();runs[i]=r;try{persist();}catch(e){runs[i]=old;throw e;}render();window.dispatchEvent(new CustomEvent('rotator:research-saved',{detail:{id:id,revision:r.revision}}));return JSON.parse(JSON.stringify(r));}});
  if(typeof window.setInterval==='function'){var ticks=0,quickTimer=window.setInterval(function(){ticks++;var el=document.getElementById('rr-quick-coin'),all=window.coins || [];if(el && all.length>1 && el.options.length<=1){el.innerHTML=all.filter(function(a){return a.id && !a.isStable;}).map(function(a){return '<option value="'+esc(a.id)+'">'+esc((a.sym || a.symbol || a.id)+' · '+(a.name || a.id))+'</option>';}).join('');el.value=pendingCoin;window.clearInterval(quickTimer);}if(ticks>40)window.clearInterval(quickTimer);},500);}
